class Solution {
public:
    vector<TreeNode*> splitBST(TreeNode* root, int target) {
        if (!root) {
            return {nullptr, nullptr};
        }
        if (root->val <= target) {
            vector<TreeNode*> parts = splitBST(root->right, target);
            root->right = parts[0];
            return {root, parts[1]};
        }
        vector<TreeNode*> parts = splitBST(root->left, target);
        root->left = parts[1];
        return {parts[0], root};
    }
};
